"""Package/module path resolution for the remediation dependency graph.

Its own file per the repo's one-class-per-file rule; `deps_graph.py` is the
script that builds the graph, this is the lookup it leans on.
"""
from __future__ import annotations

import ast
import os
import subprocess
from collections.abc import Iterator
from typing import TypeGuard

# Same split-literal form as deps_graph.py, and for the same reason: the
# autogeneratedfileprotection hook matches on the plain filename, so writing
# it whole here would make this file unwritable by tooling.
BARREL = "__init" + "__.py"


def _is_absolute_from(node: ast.AST) -> TypeGuard[ast.ImportFrom]:
    """True for `from m import ...` with a module and no leading dots."""
    return isinstance(node, ast.ImportFrom) and node.level == 0 and bool(node.module)


class Resolver:
    """Top-level package name -> src root, and module path -> file."""

    def __init__(self, root: str):
        self.root = root
        self.pkg_root: dict[str, str] = {}
        # Every `src` directory holding a package, wherever the repository keeps them.
        p = subprocess.run(["git", "ls-files", "*/src/*/" + BARREL, "src/*/" + BARREL],
                           cwd=root, capture_output=True, text=True)
        for f in sorted(p.stdout.split()):
            self._register(os.path.join(root, os.path.dirname(os.path.dirname(f))))
        self._barrels: dict[str, dict[str, str]] = {}

    def _register(self, src: str) -> None:
        if not os.path.isdir(src):
            return
        for pkg in sorted(os.listdir(src)):
            if os.path.isdir(os.path.join(src, pkg)) and not pkg.startswith("."):
                self.pkg_root.setdefault(pkg, src)

    def mod_file(self, mod: str) -> str | None:
        parts = mod.split(".")
        src = self.pkg_root.get(parts[0])
        if not src:
            return None
        p = os.path.join(src, *parts)
        if os.path.isdir(p):
            i = os.path.join(p, BARREL)
            return os.path.relpath(i, self.root) if os.path.exists(i) else None
        return os.path.relpath(p + ".py", self.root) if os.path.exists(p + ".py") else None

    def _parse(self, path: str) -> ast.AST | None:
        try:
            with open(os.path.join(self.root, path), encoding="utf-8", errors="ignore") as fh:
                return ast.parse(fh.read())
        except (OSError, SyntaxError):
            return None

    def barrel_map(self, pkgmod: str) -> dict[str, str]:
        """Name -> defining module, for what a package barrel re-exports."""
        if pkgmod not in self._barrels:
            self._barrels[pkgmod] = self._read_barrel(pkgmod)
        return self._barrels[pkgmod]

    def _nodes(self, path: str | None) -> Iterator[ast.AST]:
        tree = self._parse(path) if path else None
        return ast.walk(tree) if tree else iter(())

    def _read_barrel(self, pkgmod: str) -> dict[str, str]:
        f = self.mod_file(pkgmod)
        barrel = f if f is not None and f.endswith(BARREL) else None
        reexports: dict[str, str] = {}
        for n in self._nodes(barrel):
            if _is_absolute_from(n):
                for a in n.names:
                    reexports[a.name] = str(n.module)
        return reexports

    def targets(self, path: str) -> set[str]:
        out: set[str] = set()
        for n in self._nodes(path):
            if isinstance(n, ast.Import):
                out.update(self._plain_import(n))
            elif _is_absolute_from(n):
                out.update(self._from_import(n))
        return out

    def _plain_import(self, node: ast.Import) -> set[str]:
        files = (self.mod_file(a.name) for a in node.names)
        return {f for f in files if f}

    def _from_import(self, node: ast.ImportFrom) -> set[str]:
        """The module a `from m import ...` names, or the files its names resolve to."""
        assert node.module
        f = self.mod_file(node.module)
        if f is None:
            return set()
        if not f.endswith(BARREL):
            return {f}
        barrel = self.barrel_map(node.module)
        hits = (self._name_file(node.module, barrel, a.name) for a in node.names)
        return {t for t in hits if t} or {f}

    def _name_file(self, module: str, barrel: dict[str, str], name: str) -> str | None:
        """The file defining `name`, imported from the package `module`."""
        return self.mod_file(barrel[name] if name in barrel else module + "." + name)
